<?php
namespace App\Services;
use App\Models\Setting; use Illuminate\Support\Facades\Cache;
class SettingsService { public const CACHE_KEY='marketplace.settings'; public function all():array{return Cache::rememberForever(self::CACHE_KEY,function(){ $rows=Setting::query()->get()->keyBy(fn($s)=>$s->group.'.'.$s->key); $out=[]; foreach(SettingsRegistry::all() as $key=>$meta){$raw=$rows[$key]??null;$v=$raw?->value??$meta['default'];$out[$key]=match($meta['type']){'integer'=>(int)$v,'boolean'=>(bool)$v,default=>$v};} return $out;});} public function get(string $key,mixed $default=null):mixed{return $this->all()[$key]??$default;} public function update(string $group,array $values):void{$registry=SettingsRegistry::all();foreach($values as $key=>$value){$full=$group.'.'.$key;if(!isset($registry[$full]))continue;if($value===null||$value===''){Setting::where(['group'=>$group,'key'=>$key])->delete();}else Setting::updateOrCreate(['group'=>$group,'key'=>$key],['value'=>(string)$value]);}Cache::forget(self::CACHE_KEY);} }
